import importlib.util
import os
from keras.src.optimizers.adam import Adam
from keras.src import ops

# Load QA test module directly from instance path
path = '/testbed/qa_instances_eval/Keras/optimizers_step_beta1_power_coupling/files/keras/src/test/optimizers/optimizers_step_beta1_power_coupling_test.py'
spec = importlib.util.spec_from_file_location('qa_test_mod', path)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

orig_update_step = Adam.update_step
records = []

def to_float(x):
    try:
        return float(ops.convert_to_numpy(x))
    except Exception:
        try:
            return float(x)
        except Exception:
            return None

def wrapped(self, gradient, variable, learning_rate):
    dtype = variable.dtype
    local_step = ops.cast(self.iterations + 1, dtype)
    beta_1_power = ops.power(ops.cast(self.beta_1, dtype), local_step)
    records.append((id(self), to_float(local_step), to_float(beta_1_power)))
    return orig_update_step(self, gradient, variable, learning_rate)

Adam.update_step = wrapped

# Run all 12 tests
cls = mod.OptimizersStepBeta1PowerCouplingQATest
obj = cls(methodName='test_case_01')
for i in range(1, 13):
    name = f'test_case_{i:02d}'
    test = cls(methodName=name)
    getattr(test, name)()

# Check invariant within each optimizer run
by_run = {}
for run_id, step, b1p in records:
    by_run.setdefault(run_id, []).append((step, b1p))

violations = []
for run_id, seq in by_run.items():
    prev = None
    for idx, (step, b1p) in enumerate(seq):
        if prev is not None:
            pstep, pb1p = prev
            if step > pstep and not (b1p < pb1p):
                violations.append((run_id, idx-1, pstep, pb1p, step, b1p))
        prev = (step, b1p)

print('total_records', len(records))
print('total_runs', len(by_run))
print('violations', len(violations))
if violations:
    print('sample_violation', violations[0])
else:
    # print a tiny sample to prove varying steps are observed
    sample = next(iter(by_run.values()))
    print('sample_first_run_pairs', sample[:6])

Adam.update_step = orig_update_step
